import fs from 'node:fs';

// Parse .env tolerantly: CRLF, comments, `export `, spaces around `=`,
// quoted values, and values that themselves contain `=`.
function parseEnv(text) {
  const out = {};
  for (const raw of text.replace(/^﻿/, '').split(/\r?\n/)) {
    const line = raw.trim();
    if (!line || line.startsWith('#')) continue;
    const m = line.match(/^(?:export\s+)?([\w.-]+)\s*=\s*(.*)$/);
    if (!m) continue;
    let v = m[2].trim();
    if (/^(["']).*\1$/.test(v)) v = v.slice(1, -1);
    out[m[1]] = v;
  }
  return out;
}

const file = fs.existsSync('.env') ? parseEnv(fs.readFileSync('.env', 'utf8')) : {};
const key = process.env.GEMINI_API_KEY || file.GEMINI_API_KEY;
if (!key) { console.error('Error: GEMINI_API_KEY is missing'); process.exit(1); }

